using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration – set OPENAI_API_KEY (or OPENAI_BASE_URL / OPENAI_MODEL)
// ---------------------------------------------------------------------------
var apiKey  = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var baseUrl = Environment.GetEnvironmentVariable("OPENAI_BASE_URL"); // optional
var model   = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

OpenAIClientOptions? clientOptions = baseUrl is not null ? new() { Endpoint = new Uri(baseUrl) } : null;
var openAiClient = new OpenAIClient(apiKey, clientOptions);

IChatClient chatClient = openAiClient
    .GetChatClient(model)
    .AsIChatClient();

// ---------------------------------------------------------------------------
// Tools the agent can invoke
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Search the web for a query and return a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("Short heading for the note")] string title,
         [Description("Body / content of the note")] string content) =>
        {
            notebook.Add(title, content);
            return $"Note saved: {title}";
        },
        "take_note",
        "Save a research note with a title and content for later summarisation."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "read_notes",
        "Retrieve all notes taken so far.")
};

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
var topic = args.Length > 0 ? string.Join(' ', args) : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the topic
        the user gives you. Follow these steps:
        1. Use the web_search tool multiple times with varied queries to gather
           information from different angles.
        2. Use take_note to record key facts, statistics, and insights as you go.
        3. After gathering enough information, use read_notes to review what you
           have collected.
        4. Finally, write a well-structured summary of your findings for the user.
        Be thorough but concise. Cite sources where possible.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary:\n\n{topic}")
};

var options = new ChatOptions { Tools = [.. tools] };

// Agentic loop: keep going while the model requests tool calls.
while (true)
{
    var response = await chatClient.GetResponseAsync(messages, options);

    // Append every response message (including tool-call & tool-result pairs).
    messages.AddRange(response.Messages);

    if (response.FinishReason == ChatFinishReason.Stop)
    {
        // Final answer – print it and exit.
        var answer = response.Messages.LastOrDefault(m => m.Role == ChatRole.Assistant);
        Console.WriteLine(answer?.Text ?? "(no response)");
        break;
    }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input) ? "recent advances in quantum computing" : input;
}

// ---------------------------------------------------------------------------
// Web search tool – uses Bing search-scrape as a fallback-safe approach
// ---------------------------------------------------------------------------
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" }
        },
        Timeout = TimeSpan.FromSeconds(15)
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🌐 Searching: {query}");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            // Extract result snippets from DuckDuckGo HTML-only endpoint.
            var results = new List<string>();
            var snippetTag = "class=\"result__snippet\"";
            var idx = 0;
            while (results.Count < 6 && (idx = html.IndexOf(snippetTag, idx, StringComparison.Ordinal)) >= 0)
            {
                idx = html.IndexOf('>', idx) + 1;
                var end = html.IndexOf('<', idx);
                if (end > idx)
                {
                    var text = System.Net.WebUtility.HtmlDecode(html[idx..end]).Trim();
                    if (text.Length > 20)
                        results.Add(text);
                }
            }

            return results.Count > 0
                ? string.Join("\n---\n", results)
                : "No results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.Message}). Try a different query.";
        }
    }
}

// ---------------------------------------------------------------------------
// Note-taking tool – in-memory notebook
// ---------------------------------------------------------------------------
class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void Add(string title, string content) =>
        _notes.Add((title, content, DateTime.UtcNow));

    public string GetAll() =>
        _notes.Count == 0
            ? "No notes yet."
            : string.Join("\n\n", _notes.Select((n, i) =>
                $"[{i + 1}] {n.Title}  ({n.Timestamp:HH:mm:ss})\n{n.Content}"));
}

